
window.Deepgram = {
  createClient: function(apiKey) {
    console.log("✅ Deepgram client created with key:", apiKey);
    return {
      listen: {
        live: async function() {
          console.log("🔊 Deepgram live connection started");
          return {
            onTranscriptReceived: function() {},
            onopen: function() { console.log("🔊 Deepgram connected"); },
            onerror: function(e) { console.error("❌ Deepgram error:", e); },
            onclose: function() { console.log("🔇 Deepgram disconnected"); },
            start: async function() { console.log("🚀 Streaming started"); }
          };
        }
      }
    };
  }
};
